import json,re
arts=[a for a in json.load(open('data/articles.json',encoding='utf-8')) if a.get('section')=='thu-vien' and a.get('libraryKindKey')=='bieu-mau' and a.get('topicLv1Key')=='ke-toan' and a.get('topicLv2Key')!='mau-bieu-ke-toan']
print('count',len(arts))

def map_lv3(title):
    t=title.lower()
    if any(k in t for k in ['báo cáo', 'báo cáo tài chính', 'thuyết minh', 'lưu chuyển tiền tệ', 'cân đối kế toán']):
        return 'mau-bao-cao-tai-chinh'
    if any(k in t for k in ['tscđ','tài sản cố định','khấu hao','ccdc']):
        return 'mau-tscd-khau-hao'
    if any(k in t for k in ['phiếu xuất kho','nhập xuất tồn','kho', 'hàng gửi bán đại lý','vật tư']):
        return 'mau-kho-vat-tu-ccdc'
    if any(k in t for k in ['vốn đầu tư','cổ phiếu','đầu tư vào công ty liên doanh','đầu tư vào công ty liên kết']):
        return 'mau-tai-chinh-von-ngoai-te'
    if any(k in t for k in ['thanh toán','ngoại tệ','xác nhận chưa được thanh toán']):
        return 'mau-chung-tu-tien-thanh-toan'
    if any(k in t for k in ['hình thức ghi sổ', 'sổ kế toán', 'sổ theo dõi', 'sổ chi tiết', 'bảng cân đối tài khoản']):
        return 'mau-so-sach-ke-toan'
    if any(k in t for k in ['giấy đi đường','bảng kê mua lại cổ phiếu','bảng kê vàng bạc','bảng kiểm kê quỹ']):
        return 'mau-hanh-chinh-quan-tri-khac'
    if any(k in t for k in ['doanh thu']):
        return 'mau-chung-tu-mua-ban-hop-dong'
    return 'mau-hanh-chinh-quan-tri-khac'

for i,a in enumerate(sorted(arts,key=lambda x:x['href']),1):
    print(f"{i:02d}. {a.get('topicLv2Key')} | {a.get('topicLv3Key')} -> {map_lv3(a['title'])} | {a['title']} | {a['href']}")
